// Generated by `xark client` from `schema.json`: a typed client for the `vote` circuit.
//
//   #[circuit]
//   fn vote(identity: Private<Identity>, path: Private<Path>, ballot: Public<Ballot>)
//
// `xark build` records the circuit's parameter types in target/xark/vote/schema.json
// and `xark client` turns them into the types below. Don't edit this file: change
// the circuit, then rebuild and rerun `xark client`. Values go in their natural
// forms (dates, strings, variant names, bytes); `@blueshift-gg/xark` encodes them against the
// schema (at the end of the imports), exactly as `xark prove
// --inputs` does.

import { CheckFailed, Circuit, Field, InputError, fromHex, toHex, type FieldInput, type Json, type Proof, type Prover, type U32, type U8, type Verifier } from "@blueshift-gg/xark/client";
export { CheckFailed, Field, InputError, fromHex, toHex };

// The circuit's schema.json.
const schema = {
  "circuit": "vote",
  "inputs": [
    {
      "name": "identity",
      "type": {
        "ref": "Identity"
      },
      "visibility": "private"
    },
    {
      "name": "path",
      "type": {
        "ref": "Path"
      },
      "visibility": "private"
    },
    {
      "name": "ballot",
      "type": {
        "ref": "Ballot"
      },
      "visibility": "public"
    }
  ],
  "public_inputs": [
    "ballot.root",
    "ballot.poll",
    "ballot.nullifier",
    "ballot.{options,choice}"
  ],
  "types": {
    "Ballot": {
      "struct": [
        {
          "name": "root",
          "type": "field"
        },
        {
          "name": "poll",
          "type": "field"
        },
        {
          "name": "nullifier",
          "type": "field"
        },
        {
          "name": "options",
          "packed": {
            "bits": 8,
            "offset": 0
          },
          "type": {
            "uint": 8
          }
        },
        {
          "name": "choice",
          "packed": {
            "bits": 8,
            "offset": 8
          },
          "type": {
            "uint": 8
          }
        }
      ]
    },
    "Identity": {
      "struct": [
        {
          "name": "nullifier_key",
          "type": "field"
        },
        {
          "name": "trapdoor",
          "type": "field"
        }
      ]
    },
    "Path": {
      "struct": [
        {
          "name": "index",
          "type": {
            "uint": 32
          }
        },
        {
          "name": "siblings",
          "type": {
            "array": {
              "len": 20,
              "of": "field"
            }
          }
        }
      ]
    }
  },
  "version": 2,
  "xark": "0.4.0"
};

/** A `Ballot` (an input struct). */
export interface Ballot {
  root: FieldInput;
  poll: FieldInput;
  nullifier: FieldInput;
  options: U8;
  choice: U8;
}

/** An `Identity` (an input struct). */
export interface Identity {
  nullifierKey: FieldInput;
  trapdoor: FieldInput;
}

/** A `Path` (an input struct). */
export interface Path {
  index: U32;
  /** Exactly 20 elements. */
  siblings: readonly FieldInput[];
}

/** Every input of `vote`. */
export interface VoteInputs {
  identity: Identity;
  path: Path;
  ballot: Ballot;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface VotePublicInputs {
  ballot: Ballot;
}

/** A `Ballot`, decoded. */
export interface BallotValue {
  root: Field;
  poll: Field;
  nullifier: Field;
  options: number;
  choice: number;
}

/** A `Path`, decoded, with its Rust methods. */
export class PathValue {
  index: number;
  siblings: Field[];

  constructor(v: {
    index: number;
    siblings: Field[];
  }) {
    this.index = v.index;
    this.siblings = v.siblings;
  }

  /**
   * The path of the leaf after this one, once `leaf` is at this path: for the next
   * free leaf's path, the next free leaf's path after adding `leaf` to the list.
   */
  next(leaf: FieldInput): PathValue {
    return Path.next(this, leaf);
  }

  /**
   * The root of the tree with `leaf` at this path. In a circuit this binds `index`
   * below 2^20, and `cond_swap` (`xark-merkle`'s, its rows proven in Lean) each
   * of its bits to 0 or 1.
   */
  root(leaf: FieldInput): Field {
    return Path.root(this, leaf);
  }

  /**
   * This path once `leaf` is at `later`, a later leaf's path: the subtree beside
   * this path that `leaf` lands in is the one sibling it changes.
   */
  update(later: Path, leaf: FieldInput): PathValue {
    return Path.update(this, later, leaf);
  }

  /**
   * For the next free leaf's path, the root of the list so far: every leaf from
   * this one on is empty.
   */
  listRoot(): Field {
    return Path.listRoot(this);
  }
}

/** The public inputs, decoded from a proof. */
export interface VotePublicValues {
  ballot: BallotValue;
}

/** The input structs, by name: what `fields` takes. */
export interface VoteStructs {
  Ballot: Ballot;
  Identity: Identity;
  Path: Path;
}

/**
 * `vote`: make a prover or verifier from a URL serving a copy of
 * `target/xark/vote/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await Vote.prover("/circuits/vote/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes()); // the proof; an exported Solana verifier reads it as is
 * const verifier = await Vote.verifier(vkBytes);
 * verifier.verify(bytes, publicInputs); // true: it proves the public inputs you require
 * ```
 */
export const Vote = new Circuit<VoteInputs, VotePublicInputs, VotePublicValues, VoteStructs>({
  name: "vote",
  schema,
  decodePublic,
  client: true,
  digest: "ce0b157239ad8e60d3ce20bccf1a7eaa",
});

export type VoteProver = Prover<VoteInputs, VotePublicInputs, VotePublicValues, VoteStructs>;
export type VoteVerifier = Verifier<VotePublicInputs, VotePublicValues, VoteStructs>;
export type VoteProof = Proof<VotePublicValues>;

/** `Ballot`'s Rust functions (`#[input] impl Ballot`), run from `client.wasm`. */
export const Ballot = {
  /**
   * `identity`, at `path`, voting `choice` of `options` in `poll`.
   */
  of(identity: Identity, path: Path, poll: FieldInput, options: U8, choice: U8): BallotValue {
    return decodeBallot(Vote.call<Json<BallotValue>>("Ballot.of", [identity, path, poll, options, choice]));
  },
};

/** `Path`'s Rust functions (`#[input] impl Path`), run from `client.wasm`. */
export const Path = {
  /**
   * The path of the leaf after this one, once `leaf` is at this path: for the next
   * free leaf's path, the next free leaf's path after adding `leaf` to the list.
   */
  next(path: Path, leaf: FieldInput): PathValue {
    return decodePath(Vote.call<Json<PathValue>>("Path.next", [path, leaf]));
  },
  /**
   * The root of the tree with `leaf` at this path. In a circuit this binds `index`
   * below 2^20, and `cond_swap` (`xark-merkle`'s, its rows proven in Lean) each
   * of its bits to 0 or 1.
   */
  root(path: Path, leaf: FieldInput): Field {
    return new Field(Vote.call<Json<Field>>("Path.root", [path, leaf]));
  },
  /**
   * The first leaf's path, in the empty list: every sibling is empty.
   */
  first(): PathValue {
    return decodePath(Vote.call<Json<PathValue>>("Path.first", []));
  },
  /**
   * This path once `leaf` is at `later`, a later leaf's path: the subtree beside
   * this path that `leaf` lands in is the one sibling it changes.
   */
  update(path: Path, later: Path, leaf: FieldInput): PathValue {
    return decodePath(Vote.call<Json<PathValue>>("Path.update", [path, later, leaf]));
  },
  /**
   * For the next free leaf's path, the root of the list so far: every leaf from
   * this one on is empty.
   */
  listRoot(path: Path): Field {
    return new Field(Vote.call<Json<Field>>("Path.list_root", [path]));
  },
};

/** `Identity`'s Rust functions (`#[input] impl Identity`), run from `client.wasm`. */
export const Identity = {
  /**
   * What a vote in `poll` reveals: `Poseidon2(nullifier_key, poll)`, the
   * compression. One per voter per poll; across polls, unlinkable without the
   * `nullifier_key`.
   */
  nullifier(identity: Identity, poll: FieldInput): Field {
    return new Field(Vote.call<Json<Field>>("Identity.nullifier", [identity, poll]));
  },
  /**
   * What the voter registers, and the list holds: `Poseidon2(nullifier_key,
   * trapdoor)`, the sponge.
   */
  commitment(identity: Identity): Field {
    return new Field(Vote.call<Json<Field>>("Identity.commitment", [identity]));
  },
};

function decodePublic(v: Json<VotePublicValues>): VotePublicValues {
  return {
    ballot: decodeBallot(v.ballot),
  };
}

function decodeBallot(v: Json<BallotValue>): BallotValue {
  return {
    root: new Field(v.root),
    poll: new Field(v.poll),
    nullifier: new Field(v.nullifier),
    options: v.options,
    choice: v.choice,
  };
}

function decodePath(v: Json<PathValue>): PathValue {
  return new PathValue({
    index: v.index,
    siblings: v.siblings.map((x) => new Field(x)),
  });
}
